## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/vertebroplastyLogic.ts`

```typescript
// Vertebroplasty / Kyphoplasty Clinical Decision Logic
// Based on:
// - VERTOS II (Klazen CA, et al. Lancet. 2010;376:1085-1092)
// - VERTOS IV (Firanescu CE, et al. BMJ. 2018;361:k1551)
// - SIR/CIRSE/ASSR/AAOS 2014 Consensus Guidelines
// - ACR Appropriateness Criteria: Vertebral Augmentation (2022)
// - NASS Coverage Policy Recommendations for Vertebral Augmentation

export type ProcedureType = "vertebroplasty" | "kyphoplasty" | "";

export type VertebroplastyInput = {
  age: string;
  procedureType: string;
  fractureLevel: string;        // T4-L5 typical range
  fractureLevels: string[];     // multiple levels
  fractureAgeWeeks: string;     // weeks since fracture
  vasScore: string;             // Visual Analog Scale 0-10
  oswestryScore: string;        // Oswestry Disability Index 0-100
  // Fracture characteristics
  acuteOnset: boolean;
  mriEdema: boolean;            // bone marrow edema on MRI
  ctFractureLine: boolean;      // fracture line on CT
  heightLoss: string;           // percent height loss
  kyphosisAngle: string;        // degrees
  posteriorWallIntact: boolean;
  // Etiology
  osteoporosis: boolean;
  malignancy: boolean;          // pathologic fracture
  trauma: boolean;
  // Conservative therapy
  conservativeWeeks: string;
  bedRestDays: string;
  analgesicsUsed: boolean;
  braceUsed: boolean;
  // Contraindications
  activeInfection: boolean;
  coagulopathy: boolean;
  spinalCordCompression: boolean;
  radiculopathy: boolean;
  allergy: boolean;
  pregnancy: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return {
    I: "Class I — Recommended",
    IIa: "Class IIa — Reasonable",
    IIb: "Class IIb — May Be Considered",
    III: "Class III — Not Recommended / Contraindicated",
  }[cor];
}

export function getCORColor(cor: COR): string {
  return {
    I: "border-green-500 text-green-700",
    IIa: "border-blue-500 text-blue-700",
    IIb: "border-yellow-500 text-yellow-700",
    III: "border-red-500 text-red-700",
  }[cor];
}

export function assessVertebroplasty(input: VertebroplastyInput) {
  const contraindications: string[] = [];
  const rationale: string[] = [];
  const optimizationSteps: string[] = [];

  // Absolute contraindications
  if (input.activeInfection) contraindications.push("Active systemic or local infection — absolute contraindication to vertebral augmentation");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy — correct INR <1.5 and platelet count >50,000 before proceeding");
  if (input.spinalCordCompression) contraindications.push("Spinal cord compression from retropulsed fragment — surgical decompression required; vertebroplasty contraindicated");
  if (input.pregnancy) contraindications.push("Pregnancy — defer elective vertebral augmentation; radiation exposure risk");
  if (input.allergy) contraindications.push("Known allergy to bone cement (PMMA) or contrast — use alternative cement or premedicate");

  if (contraindications.length > 0) {
    return {
      recommendation: "Vertebral Augmentation Contraindicated",
      cor: "III" as COR,
      loe: "C",
      urgency: "Contraindicated",
      rationale: ["Absolute contraindication(s) identified — address before proceeding."],
      contraindications,
      optimizationSteps: ["Resolve contraindication(s) before reassessing candidacy"],
      procedureNote: "",
    };
  }

  const vas = parseFloat(input.vasScore) || 0;
  const oswestry = parseFloat(input.oswestryScore) || 0;
  const fractureWeeks = parseFloat(input.fractureAgeWeeks) || 0;
  const heightLoss = parseFloat(input.heightLoss) || 0;
  const conservWeeks = parseFloat(input.conservativeWeeks) || 0;

  let cor: COR = "IIb";
  let urgency = "Elective";

  // ACR Appropriateness Criteria: Usually Appropriate
  if (
    input.mriEdema &&
    fractureWeeks <= 6 &&
    vas >= 4 &&
    (input.osteoporosis || input.malignancy) &&
    input.posteriorWallIntact
  ) {
    cor = "I";
    urgency = fractureWeeks <= 2 ? "Acute Fracture — Expedited" : "Subacute Fracture — Appropriate";
    rationale.push(`Acute/subacute vertebral compression fracture (${fractureWeeks} weeks) with MRI-confirmed bone marrow edema`);
    rationale.push(`VAS pain score ${vas}/10 — severe pain supporting intervention`);
    rationale.push("Posterior vertebral wall intact — safe for vertebral augmentation");
    if (input.malignancy) {
      rationale.push("Pathologic fracture from malignancy — vertebral augmentation provides rapid pain relief and structural stabilization");
    } else {
      rationale.push("Osteoporotic vertebral compression fracture — ACR Appropriateness Criteria: Usually Appropriate for vertebral augmentation");
    }
    if (conservWeeks < 2) {
      rationale.push("Note: Short conservative therapy trial — most payers require ≥2–6 weeks unless pain is refractory or patient is hospitalized");
      optimizationSteps.push("Document failed conservative therapy or medical necessity for early intervention");
    }
  } else if (
    (input.mriEdema || input.ctFractureLine) &&
    fractureWeeks <= 12 &&
    vas >= 4 &&
    conservWeeks >= 2 &&
    input.posteriorWallIntact
  ) {
    cor = "IIa";
    urgency = "Reasonable";
    rationale.push(`Vertebral compression fracture (${fractureWeeks} weeks) with imaging-confirmed fracture`);
    rationale.push(`Conservative therapy trial: ${conservWeeks} weeks`);
    rationale.push("Vertebral augmentation is reasonable for persistent pain after conservative management");
  } else if (fractureWeeks > 12 && input.mriEdema) {
    cor = "IIb";
    urgency = "Chronic Fracture with Persistent Edema";
    rationale.push(`Fracture age ${fractureWeeks} weeks — chronic fracture`);
    rationale.push("MRI bone marrow edema suggests fracture non-union or pseudarthrosis — augmentation may still be beneficial");
    optimizationSteps.push("Consider dynamic MRI or SPECT-CT to confirm fracture activity before proceeding");
    optimizationSteps.push("Most payers limit coverage to fractures <12 months old with imaging evidence of acuity");
  } else if (!input.mriEdema && !input.ctFractureLine) {
    cor = "IIb";
    urgency = "Imaging Evidence Required";
    rationale.push("MRI bone marrow edema or CT fracture line not documented — imaging confirmation required");
    optimizationSteps.push("Obtain MRI with STIR/fat-suppressed sequences to confirm acute fracture and bone marrow edema");
    optimizationSteps.push("CT can confirm fracture line if MRI is contraindicated");
  } else if (conservWeeks < 2) {
    cor = "IIb";
    urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient — most payers require ≥2–6 weeks");
    optimizationSteps.push("Continue analgesics, bracing, and activity modification for ≥6 weeks");
    optimizationSteps.push("Document pain scores and functional status at each visit");
  } else {
    cor = "IIb";
    urgency = "Insufficient Criteria";
    optimizationSteps.push("Confirm MRI bone marrow edema or CT fracture line");
    optimizationSteps.push("Document VAS ≥4 and functional impairment");
    optimizationSteps.push("Complete ≥6-week conservative therapy trial");
  }

  if (!input.posteriorWallIntact) {
    rationale.push("Posterior vertebral wall compromise — increased risk of cement extravasation; kyphoplasty preferred over vertebroplasty; neurosurgery consultation recommended");
  }

  if (heightLoss >= 50) {
    rationale.push(`Severe vertebral height loss (${heightLoss}%) — kyphoplasty may restore height better than vertebroplasty`);
  }

  if (input.radiculopathy) {
    optimizationSteps.push("Radiculopathy present — evaluate for foraminal compromise; consider nerve root block or surgical decompression if radicular pain predominates");
  }

  // Procedure note
  let procedureNote = "";
  if (input.procedureType === "kyphoplasty") {
    procedureNote = "Kyphoplasty (balloon-assisted): Creates cavity before cement injection, allows height restoration, lower cement extravasation risk. Preferred for: height loss >30%, kyphosis >15°, posterior wall compromise, thoracolumbar junction fractures.";
  } else if (input.procedureType === "vertebroplasty") {
    procedureNote = "Vertebroplasty: Direct cement injection without balloon. Faster, lower cost, comparable pain relief to kyphoplasty in most RCTs. Preferred for: acute fractures with minimal height loss, malignant fractures requiring rapid stabilization.";
  } else {
    procedureNote = "Both vertebroplasty and kyphoplasty provide equivalent pain relief (VERTOS II). Kyphoplasty offers potential height restoration and lower extravasation risk at higher cost. Choice depends on fracture morphology, height loss, and operator preference.";
  }

  return {
    recommendation:
      cor === "I"
        ? "Vertebral Augmentation Recommended"
        : cor === "IIa"
        ? "Vertebral Augmentation Reasonable"
        : urgency === "Continue Conservative Therapy"
        ? "Continue Conservative Therapy — Augmentation Premature"
        : urgency === "Imaging Evidence Required"
        ? "MRI/CT Imaging Required Before Proceeding"
        : "Insufficient Criteria for Vertebral Augmentation",
    cor,
    loe: input.mriEdema && fractureWeeks <= 6 ? "A" : "B",
    urgency,
    rationale,
    contraindications,
    optimizationSteps,
    procedureNote,
  };
}
```


